<script setup lang="ts">
import { computed,onMounted,onBeforeUnmount,reactive,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { leaveApi } from '../api/leave';import { useRoute,useRouter,onBeforeRouteLeave } from 'vue-router';
const route=useRoute(),router=useRouter(),saving=ref(false),dirty=ref(false);const form=reactive({leaveType:'ANNUAL',startTime:'',endTime:'',reason:''});const hours=computed(()=>form.startTime&&form.endTime?Math.max(0,(+new Date(form.endTime)-+new Date(form.startTime))/3600000):0);
async function save(submit=false){if(!form.startTime||!form.endTime||hours.value<=0||!form.reason.trim())return ElMessage.warning('请完整填写且结束时间晚于开始时间');if(submit)await ElMessageBox.confirm('保存后立即提交审批？','提交确认');saving.value=true;try{const body={...form,startTime:new Date(form.startTime).toISOString(),endTime:new Date(form.endTime).toISOString()};let id=Number(route.params.id);if(id)await leaveApi.update(id,body);else{id=(await leaveApi.create(body) as any).data.id}if(submit)await leaveApi.submit(id);dirty.value=false;ElMessage.success(submit?'已提交审批':'草稿已保存');router.push('/leave')}finally{saving.value=false}}
onMounted(async()=>{if(route.params.id){const r:any=await leaveApi.detail(Number(route.params.id));Object.assign(form,r.data);form.startTime=form.startTime?.slice(0,16);form.endTime=form.endTime?.slice(0,16)}});onBeforeRouteLeave(()=>dirty.value?confirm('表单尚未保存，确认离开？'):true);onBeforeUnmount(()=>{});
</script>
<template><div class="page-title"><h1>{{route.params.id?'编辑':'新建'}}请假申请</h1><p>时长由系统根据起止时间自动计算</p></div><el-card><el-form label-width="100px" style="max-width:720px" @change="dirty=true"><el-form-item label="请假类型" required><el-select v-model="form.leaveType"><el-option label="年假" value="ANNUAL"/><el-option label="病假" value="SICK"/></el-select></el-form-item><el-form-item label="开始时间" required><el-date-picker v-model="form.startTime" type="datetime" value-format="YYYY-MM-DDTHH:mm"/></el-form-item><el-form-item label="结束时间" required><el-date-picker v-model="form.endTime" type="datetime" value-format="YYYY-MM-DDTHH:mm"/></el-form-item><el-form-item label="请假时长"><b>{{hours.toFixed(2)}} 小时</b></el-form-item><el-form-item label="请假原因" required><el-input v-model="form.reason" type="textarea" maxlength="500" show-word-limit :rows="5"/></el-form-item><el-form-item><el-button :loading="saving" @click="save(false)">保存草稿</el-button><el-button type="primary" :loading="saving" @click="save(true)">保存并提交</el-button></el-form-item></el-form></el-card></template>
